let pendingPatterns={},pendingScene=null,voices=new Map(),loopVoices=new Map(),activePunches=new Map(),songPosition=0,songCycle=0,countIn=0,recordingMaster=false,sampling=false,tingConnected=false,tingEffect='echo',tingSlot=0,tingMod=.5,tingSamples=['airhorn','siren','laser','cowbell'],repeatDivision=0,heldPads=new Map(),repeatTimer=null,installEvent=null,tapTimes=[],sampleOriginGroup=0,sampleOriginPad=0,editPage=0;
