function drawWave(){const canvas=$('#waveform');if(!canvas)return;const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);c.fillStyle='#eaf0df';c.fillRect(0,0,w,h);c.strokeStyle='#0b4936';c.lineWidth=1;const buf=A.samples.get(S.selected.sound.replace('sample:',''));c.beginPath();if(buf){const data=buf.getChannelData(0);for(let x=0;x<w;x++){const start=Math.floor(x/w*data.length),end=Math.min(data.length,start+Math.ceil(data.length/w));let lo=0,hi=0;for(let i=start;i<end;i++){lo=Math.min(lo,data[i]);hi=Math.max(hi,data[i]);}c.moveTo(x,h/2+lo*h*.44);c.lineTo(x,h/2+hi*h*.44);}}else{for(let x=0;x<w;x++){const y=h/2+Math.sin(x*.28)*(Math.sin(x*.03)*.25+.7)*Math.exp(-x/w*3)*h*.4;x?c.lineTo(x,y):c.moveTo(x,y);}}c.stroke();if(!buf){c.fillStyle='#68776e';c.font='10px monospace';c.fillText('SYNTH / ILLUSTRATIVE WAVEFORM',9,91);}}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();bind($('#modal-content'));}
function closeModal(){if(samplingWaiting){samplingWaiting=false;sampleCaptureToken++;clearInterval(sampleWaitTimer);if(!tingConnected)A.disableMic();}if($('#modal').open)$('#modal').close();}
function inputModal(title,label,value,onSave){modal(`<h2>${title}</h2><label class="field">${label}<input id="modal-input" value="${esc(value)}" style="width:100%;margin-top:8px" maxlength="80"></label><button id="modal-save" class="primary">Save</button>`);$('#modal-save').onclick=()=>{onSave($('#modal-input').value.trim()||value);closeModal();render();};$('#modal-input').focus();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);return name;}
function tingState(){return {samples:[...tingSamples],effect:tingEffect,mod:tingMod,config:tingConfig,customOn:tingCustomOn,preset:tingRackPos,sampleMode:tingSampleMode,sampleModes:[...tingSlotModes]};}
async function saveTingState(){S.ting=tingState();if(S.namespace)await S.save();else await S.dbPut('ting',S.ting);}
function restoreTingState(t){if(!t)return;tingSamples=t.samples||tingSamples;tingEffect=t.effect||tingEffect;tingMod=t.mod??tingMod;tingConfig=t.config||null;tingCustomOn=!!t.customOn;tingRackPos=t.preset||0;tingSlotModes=t.sampleModes||['oneshot','oneshot','oneshot','oneshot'];tingSampleMode=t.sampleMode||tingSlotModes[tingSlot]||'oneshot';}
