async function chop(){if(manualChop)return finishManualChop();const b=A.samples.get(S.selected.sound.replace('sample:',''));if(!b)return toast('Import or resample audio before chopping.');modal(`<h2>Chop ${esc(soundName(S.selected))}</h2><p>Chops share the source audio and keep separate trim points. They fill pads from your selected pad onward, replacing the assignments; Undo restores them.</p><label class="field">Slices <select id="chop-count">${[2,4,8,12].map(n=>`<option>${n}</option>`).join('')}</select></label><label class="field">Method <select id="chop-mode"><option value="equal">Equal length</option><option value="transient">Detect attacks</option><option value="manual">Live cuts · tap pads</option></select></label><button id="chop-go" class="primary">Make slices</button>`);$('#chop-go').onclick=()=>{const count=Number($('#chop-count').value),mode=$('#chop-mode').value,source=clone(S.selected),start=source.start,end=source.end,points=[start];if(mode==='manual'){manualChop={source,buffer:b,group:S.group,pad:S.pad,points,startTime:A.ctx.currentTime,voice:A.trigger({...source,mode:'key'},A.ctx.currentTime,.8,0,S.group)};closeModal();render();toast('Tap a pad to mark each cut, then Finish chopping.');return;}if(mode==='transient'){const d=b.getChannelData(0);let energies=[];for(let i=Math.floor(start*d.length);i<end*d.length;i+=512){let energy=0;for(let j=i;j<Math.min(i+512,d.length);j++)energy+=d[j]*d[j];energies.push({pos:i/d.length,energy});}energies=energies.filter((a,i,v)=>i>0&&a.energy>v[i-1].energy*2).sort((a,b)=>b.energy-a.energy);for(const e of energies)if(points.every(p=>Math.abs(p-e.pos)>(end-start)/count/2)&&points.length<count)points.push(e.pos);}while(points.length<count)points.push(start+(end-start)*points.length/count);points.sort((a,b)=>a-b);points.push(end);mutate(()=>{for(let n=0;n<count&&S.pad+n<12;n++)S.g.pads[S.pad+n]={...source,name:`${soundName(source)} ${n+1}`,start:points[n],end:points[n+1],mode:'oneshot'};});closeModal();render();toast('Slices ready. Tap the pads to audition.');};}
function patternTools(){modal(`<h2>Pattern ${S.g.pattern} · ${'ABCD'[S.group]}</h2><p>${S.pattern.events.length} notes · ${S.pattern.length/barSteps()} bars. Edits have Undo.</p><div class="row"><button data-action="duplicate-pattern">Duplicate to next free slot</button><button data-action="copy">Copy pattern</button><button data-action="paste">Paste pattern</button><button data-action="clear-pattern" class="danger">Clear notes</button></div><label class="field">Choose any of 99 patterns <input id="any-pattern" type="number" min="1" max="99" value="${S.g.pattern}"></label><button id="any-pattern-go">Open pattern</button>${range('swing','Swing',S.p.swing,0,.6,.01)}<label><input id="quantize" type="checkbox" ${S.p.quantize?'checked':''}>Quantize live input</label><div class="row" style="margin-top:14px"><button data-action="quantize-notes">Correct selected pad to chosen grid</button><button data-action="nudge-left">Nudge selected pad −1 tick</button><button data-action="nudge-right">Nudge selected pad +1 tick</button></div>`);$('#any-pattern-go').onclick=()=>{queuePattern(S.group,Number($('#any-pattern').value));closeModal();};$('#swing').oninput=e=>{S.p.swing=Number(e.target.value);$('#swing-out').value=S.p.swing.toFixed(2);S.changed();};$('#quantize').onchange=e=>{S.p.quantize=e.target.checked;S.changed();};}
function eventEditor(){const events=S.pattern.events.map((e,i)=>({...e,index:i})).filter(e=>e.pad===S.pad);modal(`<h2>Notes · ${esc(soundName(S.selected))}</h2><p>Step positions allow 1/24 of a sixteenth note (96 ticks per quarter). Durations are quarter-note beats.</p><div style="overflow-x:auto"><table><thead><tr><th>Step</th><th>Note</th><th>Velocity</th><th>Length</th><th>Chance</th><th></th></tr></thead><tbody>${events.map(e=>`<tr data-event="${e.index}"><td><input data-ev="step" type="number" step=".0416666667" min="0" max="${S.pattern.length-1/24}" value="${e.step.toFixed(3)}" style="width:65px"></td><td><input data-ev="note" type="number" min="-48" max="48" value="${e.note}" style="width:55px"></td><td><input data-ev="velocity" type="number" min=".01" max="1" step=".05" value="${e.velocity}" style="width:60px"></td><td><input data-ev="duration" type="number" min=".01041667" max="4" step=".0625" value="${e.duration}" style="width:60px"></td><td><input data-ev="probability" type="number" min="0" max="1" step=".1" value="${e.probability??1}" style="width:60px"></td><td><button data-delete-event="${e.index}">×</button></td></tr>`).join('')}</tbody></table></div>${events.length?'':'<p>No notes yet. Tap steps or record pads first.</p>'}<button id="events-save" class="primary" style="margin-top:15px">Apply note edits</button>`);$('#events-save').onclick=()=>{const updates=$$('[data-event]',$('#modal-content')).map(tr=>({index:Number(tr.dataset.event),values:Object.fromEntries($$('[data-ev]',tr).map(e=>[e.dataset.ev,Number(e.value)]))}));if(updates.some(u=>Object.values(u.values).some(v=>!Number.isFinite(v))))return toast('Enter valid numbers.');mutate(()=>updates.forEach(u=>{const e=S.pattern.events[u.index],v=u.values;e.step=Math.max(0,Math.min(S.pattern.length-1/24,v.step));e.note=Math.max(-48,Math.min(48,v.note));e.velocity=Math.max(.01,Math.min(1,v.velocity));e.duration=Math.max(1/96,Math.min(4,v.duration));e.probability=Math.max(0,Math.min(1,v.probability));}));closeModal();render();};$$('[data-delete-event]').forEach(b=>b.onclick=()=>{mutate(()=>S.pattern.events.splice(Number(b.dataset.deleteEvent),1));eventEditor();});}
function songDialog(){modal(`<h2>Arrange your song</h2><p>Commit a few scenes, then choose their order. One scene plays for its longest pattern. Up to 99 song positions.</p><label class="field">Scene numbers in order (for example 1, 1, 2, 3)<input id="song-order" value="${S.p.song.map(n=>n+1).join(', ')}" placeholder="1, 1, 2, 3" style="width:100%;margin-top:8px"></label><label class="field"><input id="song-on" type="checkbox" ${S.p.songOn?'checked':''}>Play song arrangement</label><label class="field"><input id="song-loop" type="checkbox" ${S.p.songLoop!==false?'checked':''}>Repeat the arrangement</label><label class="field">Scene changes<select id="scene-transition">${[['immediate','Immediately'],['bar','At the next bar'],['pattern','At the end of the pattern']].map(([v,n])=>`<option value="${v}" ${(S.p.sceneChange||'bar')===v?'selected':''}>${n}</option>`).join('')}</select></label><button id="song-save" class="primary">Use arrangement</button><div class="feature-note">Scenes reference patterns. Edit a pattern and every scene using it hears the change. Commit duplicates patterns so a variation can be edited independently.</div>`);$('#song-save').onclick=()=>{const raw=$('#song-order').value.trim(),arr=raw?raw.split(/[ ,]+/).map(Number):[];if(arr.length>99||arr.some(n=>!Number.isInteger(n)||n<1||n>S.p.scenes.length))return toast('Use existing scene numbers; maximum 99 positions.');mutate(()=>{S.p.song=arr.map(n=>n-1);S.p.songOn=$('#song-on').checked;S.p.songLoop=$('#song-loop').checked;S.p.sceneChange=$('#scene-transition').value;});songPosition=0;closeModal();render();};}
function exportDialog(){modal(`<h2>Take your music with you</h2><p>Export the current mix to stereo WAV, or capture a live performance with your pad hits and effects.</p><label class="field">Bars <input id="export-bars" type="number" min="1" max="99" value="${Math.max(1,Math.ceil(Math.max(...S.p.groups.map(g=>g.patterns[g.pattern].length))/barSteps()))}"></label><label class="field"><input id="export-song" type="checkbox" ${S.p.songOn&&S.p.song.length?'checked':''}> Render the song arrangement</label><div class="row"><button id="export-wav" class="primary">Render WAV</button><button data-action="ting-record">${recordingMaster?'Stop & save live capture':'Start live capture'}</button><button data-action="save-project">Save editable project</button></div><p class="muted" style="margin-top:15px">WAV renders patterns and loops, or the scene arrangement when selected. Browser export is limited to 128 bars per render. Live capture includes microphone and performance moves, in the format supported by your browser. Keep a project backup too.</p>`);$('#export-wav').onclick=safely(async()=>{const bars=Math.max(1,Math.min(99,Number($('#export-bars').value)||4));$('#export-wav').disabled=true;$('#export-wav').textContent='Rendering…';await ensureAudio();const song=$('#export-song').checked;const exportBars=song?S.p.song.reduce((n,i)=>n+Math.ceil(Math.max(...S.p.scenes[i].patterns.map((pat,g)=>S.p.groups[g].patterns[pat].length))/barSteps()),0):bars;if(exportBars>128)throw new Error('This song is longer than the 128-bar WAV-render limit. Use live capture for the full performance.');const b=await A.render(S.p,exportBars,{song});download(b,`${slug()}-${bars}bars.wav`);closeModal();toast('WAV exported');});}
async function capture(){await ensureAudio();if(recordingMaster){const b=await A.stopRecording();recordingMaster=false;download(b,`${slug()}-live.${b.type.includes('mp4')?'m4a':b.type.includes('ogg')?'ogg':'webm'}`);toast('Live performance saved');}else{A.startRecording();recordingMaster=true;toast('Capturing your performance. Press Stop capture to save.');}closeModal();render();}
function guide(){modal(`<h2>A little help. Then play.</h2><div class="tutorial-step"><b>1 · Start with a groove</b>Press Play to hear the demo. Mute a track with its ● button. Each variation tile chooses a pattern; empty tiles are ready for your music.</div><div class="tutorial-step"><b>2 · Make it yours</b>Select a pad, choose a sound, and tap the sixteen steps. Choose Record and play pads to overdub. Stopped recording gives a four-beat count-in.</div><div class="tutorial-step"><b>3 · Add bass and melody</b>Choose group B or C, select a sound, then Scale keyboard. The twelve keys stay in your selected scale. Record adds the notes to that group.</div><div class="tutorial-step"><b>4 · Build and perform</b>Commit variation saves a scene and duplicates the patterns for editing. Arrange scene numbers in Song arrangement. Live lock prevents edits; track mutes and momentary effects stay playable.</div><div class="tutorial-step"><b>5 · Bring your own sound</b>Import WAV, MP3 or other browser-supported audio. For a private .riddimbank.json file, choose Import sound bank in Sound desk or the ••• Studio menu on a small screen, then select a pad and pick its sound under Your samples. Imports stay in this browser on this device. Bank provenance and ownership are supplied by the creator; verify your rights before sharing a bank, project backup or saved HTML. Root note and BPM are stored as information; set pad MIDI root and loop BPM yourself if needed. Sample the mic or resample your beat. Open Shape & sample editor for trim, reverse and chop. Loop pads toggle audibility while the audio keeps running in time.</div><p><b>Keyboard:</b> Q W E / A S D / Z X C / V B N play pads. Space play/pause; Esc stops; R arms record; K toggles keys; 1–4 select groups; Ctrl/⌘ Z undo, Shift Ctrl/⌘ Z redo. Keys do not trigger while typing.</p><div class="row"><button data-action="midi">MIDI setup</button><button data-action="install">Install & offline</button><button data-action="fidelity">Features & fidelity</button><button data-action="save-html">Save HTML</button><button data-action="share-html">Share file</button></div>`);}
function tutorial(){guide();storage.setItem('riddim-onboarded','1');}
function fidelity(){modal(`<h2>What this instrument recreates</h2><p>This is an independent open-source browser instrument based on the EP–40 guide v2.5 and tutorial transcripts. It is a functional recreation, with deliberate easier controls.</p><table><tr><th>Area</th><th>Current behaviour</th></tr><tr><td>Music model</td><td>9 sessions, 4 groups × 12 pads, up to 99 patterns and scenes, commit/undo, step and live recording, song order.</td></tr><tr><td>Audio</td><td>46 recreated presets, 39 hosted recreated samples, ten Supertone-style slots and three sirens; imported samples; seven send effects and twelve recreated punch actions.</td></tr><tr><td>Original audio</td><td>No full factory bank or artist projects. No manufacturer sounds or configuration packs are bundled. Download and import any sounds you are entitled to use.</td></tr><tr><td>Sampling</td><td>Mic, audio-file import, offline resampling, equal or attack chops, trim, reverse and loop mute. Browser audio input selection replaces physical line/USB sockets.</td></tr><tr><td>Ting</td><td>Push-to-talk, four replaceable samples, four voice effects and handle controls. No physical shake sensor or matched analog microphone colour.</td></tr><tr><td>Known differences</td><td>Firmware button combinations, exact punch mapping/DSP, hardware timing and analog connections are not identical. Browser synthesis, stretching, legato and effects are reconstructed algorithms. Read the delivered feature audit for tested coverage.</td></tr></table><p>Exact sound matching requires the instrument, source sounds and listening comparisons. Recreated sounds are clearly labelled. Browser checks are separate from your musical acceptance.</p><p><a href="https://teenage.engineering/guides/ep-40" target="_blank" rel="noopener">Official EP–40 guide</a> · <a href="https://teenage.engineering/guides/ep-2350/ting" target="_blank" rel="noopener">Ting guide</a> · <a href="https://teenage.engineering/downloads/ep-2350/sound-packs" target="_blank" rel="noopener">Official add-on packs</a></p>`);}
function installGuide(){modal(`<h2>Install RiddimTing</h2><p>On this Mac, open the local app in Chrome or Edge and choose <b>Install RiddimTing</b> from the address bar or browser menu. In Safari, use <b>File → Add to Dock</b>.</p><p>Once the app reports “Ready offline”, it can reopen without the internet. Keep a project backup: browser storage can be cleared by the browser.</p><p>The single-file HTML copy opens directly offline and includes the app and a session snapshot. Installing a PWA needs localhost or HTTPS; a file opened from disk cannot install a service worker.</p><p>On a phone or tablet, installing needs an HTTPS address or a trusted local setup. Open babyfreakout.com/app/ to install this hosted version. Desktop responsive checks do not certify a physical phone.</p><button data-action="save-html" class="primary">Save standalone HTML</button><button data-action="save-project">Back up project</button>`);}
async function saveHTML(share=false){
 let html;
 if(location.protocol==='file:'||$('#session-snapshot')){
  html='<!doctype html>\n'+document.documentElement.outerHTML;
  html=html.replace(/<script id="session-snapshot"[\s\S]*?<\/script>/,'');
 }else{
  const names=['bank.js','sound-library.js','session.js','engine.js','packs.js','ting-config.js','app.js'];
  const stylesheet=$('link[rel=stylesheet]')?.getAttribute('href')||'style.css';const paths=['index.html',stylesheet,...names.map(n=>$$('script[src]').find(s=>s.getAttribute('src').split('?')[0]===n)?.getAttribute('src')||n)];const [base,css,...scripts]=await Promise.all(paths.map(n=>fetch(n,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(`Cannot read ${n}`);return r.text();})));
  html=base.replace(/<link rel="stylesheet"[^>]*>/,()=>`<style>${css}</style>`).replace(/<link rel="manifest"[^>]*>/,'').replace(/<link rel="(?:icon|apple-touch-icon)"[^>]*>/g,'');
  html=html.replace(/<script src="([^"]+)"><\/script>/g,(tag,source)=>{
   const n=source.split('?')[0],i=names.indexOf(n);if(i<0)return tag;
   const code=scripts[i].replaceAll('</script','<'+String.fromCharCode(92)+'/script');
   return `<script data-source="${n}">${code}</script>`;
  });
 }
 const snapshot=portableSession().replaceAll('<',String.fromCharCode(92)+'u003c');
 html=html.replace('</head>',()=>`<script id="session-snapshot" type="application/json">${snapshot}</script></head>`);
 const file=new File([html],`${slug()}-studio.html`,{type:'text/html'});
 if(share&&navigator.canShare?.({files:[file]})){
  try{await navigator.share({files:[file],title:'RiddimTing — Baby Freakout'});toast('HTML file passed to the share sheet');return;}
  catch(e){if(e.name==='AbortError')return;}
 }
 download(file,file.name);
 toast(share?'Native file sharing unavailable. Attach the downloaded HTML file privately.':'Standalone HTML saved. Attach that file to share it privately.');
}
async function officialPacks(){modal(`<h2>Bring your own sounds</h2><p>This edition includes synthesized presets and hosted recreated samples. Personal music-making in Baby Freakout is permitted; redistribution of raw hosted sample assets is not granted. Manufacturer WAVs and FX configurations are not bundled because they do not carry an open-source redistribution licence.</p><p>Download files you are entitled to use, extract them on your device, then choose <b>Import sounds</b>. In Ting, use <b>Custom FX & presets → Import config JSON</b> for configurations. Match sample filenames when a configuration names them.</p><p><a href="https://teenage.engineering/downloads/ep-2350/sound-packs" target="_blank" rel="noopener">Manufacturer add-on downloads ↗</a></p><button data-action="import-sample" class="primary">Import sounds</button><p class="muted">Imports stay on your device. Check each pack’s terms before sharing it in music projects or HTML snapshots.</p>`);}
async function ensureTingRack(){
 await ensureAudio();if(!tingConfig)throw new Error('Load a Ting configuration first.');
 if(!tingRack)tingRack=new TingRack(A);
 if(tingRack.config!==tingConfig){tingConfig=tingRack.load(tingConfig);}
 if(!tingConfig.presets.some(p=>p.pos===tingRackPos))tingRackPos=tingConfig.presets[0].pos;
 if(!tingRack.attached)tingRack.attach();
 if(tingRack.position!==tingRackPos)tingRack.select(tingRackPos);
 tingRack.setHandle(tingMod);return tingRack;
}
async function tingBuffer(sound){
 if(sound.startsWith('sample:')){const b=A.samples.get(sound.slice(7));if(!b)throw new Error('Import the audio for this Ting slot first.');return b;}
 if(tingSampleBuffers.has(sound))return tingSampleBuffers.get(sound);
 const p=makeProject();p.bpm=120;p.master=1;p.groups.forEach((g,i)=>{g.mute=i!==0;g.volume=1;g.send=0;g.patterns[1]={length:16,events:[]};});p.groups[0].pads[0]=makePad(sound);p.groups[0].patterns[1].events=[{step:0,pad:0,velocity:.8,note:0,duration:.5,probability:1}];
 const raw=await A.ctx.decodeAudioData(await(await A.render(p,1)).arrayBuffer()),frames=Math.min(raw.length,raw.sampleRate*2),b=A.ctx.createBuffer(raw.numberOfChannels,frames,raw.sampleRate);for(let ch=0;ch<b.numberOfChannels;ch++)b.copyToChannel(raw.getChannelData(ch).subarray(0,frames),ch);tingSampleBuffers.set(sound,b);while(tingSampleBuffers.size>16)tingSampleBuffers.delete(tingSampleBuffers.keys().next().value);return b;
}
function fileStem(value){let name=String(value).split('·')[0].trim().split('/').at(-1);const dot=name.lastIndexOf('.');return (dot>0?name.slice(0,dot):name).toLowerCase();}
async function triggerTingSample(){
 await ensureAudio();
 if(tingCustomOn){const rack=await ensureTingRack();let sound=tingSamples[tingSlot];const def=tingConfig.samples?.find((s,i)=>(s.pos??i)===tingSlot);if(def){const stem=def.file.replace(/\.[^.]+$/,'').toLowerCase(),match=Object.entries(S.sampleData).find(([,s])=>s.name.toLowerCase().replace(/\s*·.*$/,'').replace(/\.[^.]+$/,'')===stem);if(match)sound=`sample:${match[0]}`;else throw new Error(`Import ${def.file} before triggering this config sample.`);}return rack.triggerSample(await tingBuffer(sound),def?.playmode||tingSampleMode);}
 if(tingSampleMode==='startstop'&&tingPartyVoice){tingPartyVoice.stop();tingPartyVoice=null;return;}
 tingPartyVoice=A.trigger({...makePad(tingSamples[tingSlot]),volume:.8,mode:tingSampleMode==='startstop'?'loop':tingSampleMode==='hold'?'key':'oneshot'},A.ctx.currentTime,.8,0,3);return tingPartyVoice;
}
async function applyTingConfig(value){
 await ensureAudio();const trial=new TingRack(A),parsed=typeof value==='string'?JSON.parse(value):clone(value);if(!parsed.presets)parsed.presets=tingConfig?.presets||Array.from({length:4},(_,pos)=>({pos,name:'Sample '+(pos+1),list:[{effect:'SAMPLE'}],trigger:{row:0}}));const config=trial.load(parsed);tingRack?.destroy();tingRack=null;tingConfig=config;for(const [i,sample]of (config.samples||[]).entries()){const pos=sample.pos??i,match=Object.entries(S.sampleData).find(([,s])=>fileStem(s.name)===fileStem(sample.file));if(match)tingSamples[pos]=`sample:${match[0]}`;tingSlotModes[pos]=sample.playmode||'oneshot';}tingSampleMode=tingSlotModes[tingSlot]||'oneshot';tingRackPos=config.presets[0].pos;tingCustomOn=true;await ensureTingRack();await saveTingState();render();toast('Ting effect configuration loaded');
}
