 play,stop:()=>pause(true),record:()=>{if(!liveAllows('record'))return toast('Record is disabled in live setup.');recordArmed=!recordArmed;if(recordArmed)S.checkpoint();render();toast(recordArmed?'Recording armed. Play for a count-in, then hit the pads.':'Recording disarmed');},
