 'project-menu':()=>{modal(`<h2>Your studio</h2><label class="field">Session <select id="session-select">${S.projects.map((p,i)=>`<option value="${i}" ${i===S.current?'selected':''}>${i+1} · ${esc(p.name)}</option>`).join('')}</select></label><div class="row"><button data-action="blank">Start a blank beat</button><button data-action="demo">Load demo groove</button><button data-action="live-demo">Build a live loop set</button><button data-action="save-project">Save project</button><button data-action="load-project">Open project</button><button data-action="import-bank">Import sound bank</button><button data-action="midi">MIDI</button><button data-action="export">Export audio</button><button data-action="resample">Resample</button><button data-action="official-packs">Add-on downloads</button></div><p class="muted">Loading a template replaces the current session. Undo restores the music. The other eight sessions stay saved.</p>`);$('#session-select').onchange=e=>{pause(true);S.selectProject(Number(e.target.value));closeModal();render();};},
