 $$('[data-pad]',root).forEach(b=>{const i=Number(b.dataset.pad);b.onpointerdown=safely(async e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(S.view==='hardware'&&hwMode==='fx'){punchDown(i,e,b);return;}if(shift&&hwMode==='sound'){S.pad=i;actions['sound-editor']();return;}await padDown(i,e);});b.onpointerup=e=>{padUp(i,e);punchUp(i,b);if(!heldPads.size)setTimeout(render,0);};b.onpointercancel=e=>{padUp(i,e);punchUp(i,b);};b.onpointermove=e=>voices.get(e.pointerId)?.voice?.pressure?.(e.pressure||.5);b.onkeydown=safely(async e=>{if((e.key==='Enter'||e.key===' ')&&!e.repeat){e.preventDefault();await padDown(i,{pointerId:`button:${i}`});}});b.onkeyup=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();padUp(i,{pointerId:`button:${i}`});render();}};});
